import { createContext, createEffect } from "solid-js";

import { createJsonResource } from "#core/ui-next/utilities/async-load.js";

import audioBase from "#core/ui/audio-base/audio-base.json?url";

interface AudioData {
	"audio-base": Record<string, string | undefined>;
	[group: string]: Record<string, string | undefined> | undefined;
}

// Load the audio data, and if it fails, show an error
const [audioData] = createJsonResource<AudioData>(audioBase);
createEffect(() => {
	if (audioData.error) {
		console.error("Error loading audio-base.json", audioData.error);
	}
});

/**
 * Plays a sound
 * @param id The sound id to play
 * @param group The sound group to play - if none is specified "audio-base" will be used
 * @returns true if the sound was able to be played
 */
export function playSound(id: string, group?: string) {
	if (audioData.loading || audioData.error) {
		return false;
	}

	const data = audioData();

	if (id.length == 0 || id == "none" || !data) {
		return false;
	}

	// need to fallback to audio-base twice to handle the case that the group exists, but the id doesn't exist in the group
	const soundTag = group ? (data[group]?.[id] ?? data["audio-base"][id]) : data["audio-base"][id];

	if (soundTag) {
		UI.sendAudioEvent(soundTag);
		return true;
	} else {
		console.error(`No sound tag found for ${id} with group ${group}`);
	}

	return false;
}

export class AudioGroupProvider {
	constructor(
		private groupName: string,
		private parent?: AudioGroupProvider,
	) {}

	/**
	 * Plays a sound for the given audio group context.
	 * If the sound is overridden on the element, play it directly.
	 * Otherwise, look it up in the audio data and play that.
	 * If the sound is still unable to be played, try again in the parent context.
	 * @param id The sound id to play
	 * @param element the element playing the sound
	 */
	public playSound(id: string, element?: HTMLElement) {
		const resolvedId = element?.getAttribute(`${id}-ref`) ?? id;
		const resolvedGroup = element?.getAttribute("data-audio-group-ref") ?? this.groupName;

		if (!playSound(resolvedId, resolvedGroup)) {
			this.parent?.playSound(resolvedId, element);
		}
	}
}

export const AudioGroupContext = createContext(() => new AudioGroupProvider("audio-base"));
